Section M.
Variables (st : mstate) (m : mem) (g : aptr) (sc : Z).
Let G := conc st g.
Let mr := get_meta_rec st g.
Let f := m_freed mr.
Hypothesis MR : ltac2:(zQ "10!lh0@4$0?5HCEIL?4HSEC?2st?1m").
Hypothesis MSL : ltac2:(zQ "10!lme@2$0?2st?1g").
Hypothesis SC : ltac2:(zQ "30!r4!lh9!lhe@2$0@2$1Z?2sc@2$2?2sc+j0").
Hypothesis FRR : 0 <= f < 2^32.
Hypothesis MW : mw_ok mr.

